function onRender(
  id: string,
  phase: string,
  actualDuration: number,
  baseDuration: number
) {
  // (A) fire-and-forget on every single commit
  fetch("/metrics", {
    method: "POST",
    body: JSON.stringify({ id, phase, actualDuration, baseDuration }),
  });
}

export function MonitoredSearch() {
  return (
    <Profiler id="search" onRender={onRender}>
      <SearchPanel />
    </Profiler>
  );
}

// build note: <Profiler> is kept in the production bundle for all users
